/bin/bash -lc "python3 /workspace/tools.py resolve run://r-001 | python3 -c 'import sys,json; d=json.load(sys.stdin);p=json.load(open(\"proposal.json\"));s=d[\"study_schema\"];
def check(v,s,path):
 if \"const\" in s: assert v==s[\"const\"],path
 if \"enum\" in s: assert v in s[\"enum\"],path
 t=s.get(\"type\")
 if t==\"object\":
  assert isinstance(v,dict),path
  assert set(s.get(\"required\",[]))<=set(v),path
  if s.get(\"additionalProperties\") is False: assert set(v)<=set(s[\"properties\"]),path
  for k,x in v.items():
   if k in s.get(\"properties\",{}): check(x,s[\"properties\"][k],path+\".\"+k)
 elif t==\"array\":
  assert isinstance(v,list) and len(v)>=s.get(\"minItems\",0),path
  for i,x in enumerate(v): check(x,s.get(\"items\",{}),path+str(i))
 elif t==\"string\": assert isinstance(v,str) and len(v)>=s.get(\"minLength\",0),path
 elif t==\"boolean\": assert isinstance(v,bool),path
check(p[\"study\"],s,\"study\"); assert p[\"study\"][\"protocol_ref\"]==d[\"required_study_protocol_ref\"]; assert set(p[\"study\"][\"evidence_refs\"])<=set(d[\"context\"][\"allowed_observation_ids\"]); assert p[\"parent_trial\"] in d[\"context\"][\"allowed_observation_ids\"]; vs=p[\"variants\"]; assert 1<=len(vs)<=4; assert len({v[\"name\"] for v in vs})==len(vs); assert len({v[\"file\"] for v in vs})==len(vs); assert any(v[\"role\"]==\"candidate\" for v in vs); assert all(v[\"role\"] in [\"candidate\",\"control\"] and v[\"file\"].endswith(\".py\") and \"/\" not in v[\"file\"] for v in vs); assert {(v[\"config\"][\"intensity_query\"],v[\"config\"][\"intensity_centering\"]) for v in vs}=={(\"target\",\"raw\"),(\"target\",\"centered\"),(\"zero\",\"raw\"),(\"zero\",\"centered\")}; assert len(p[\"knowledge_assessments\"])==5; assert all(x[\"decision\"] in [\"used\",\"considered\",\"rejected\",\"unresolved\"] for x in p[\"knowledge_assessments\"]); print(\"Runtime study schema, evidence IDs, protocol, four-cell factorial and five knowledge assessments validated.\")'"

